def landing_checksum(target: Landing) -> tuple[int, str]:
    ids = sorted(target.by_id)
    digest = hashlib.md5(",".join(ids).encode()).hexdigest()
    return len(ids), digest


def payload_digest(rows: list[SourceRow]) -> str:
    parts = [f"{r.source_id}:{r.payload}" for r in sorted(rows, key=lambda r: r.source_id)]
    return hashlib.md5(",".join(parts).encode()).hexdigest()


def landing_payload_digest(target: Landing) -> str:
    parts = [f"{i}:{target.by_id[i].payload}" for i in sorted(target.by_id)]
    return hashlib.md5(",".join(parts).encode()).hexdigest()

